#!/usr/bin/env bash
# Compile a MicroJava program and run it on the MicroJava VM (runs inside the Docker image).
#
#   mjc.sh [--verbose] [--disasm] [--no-run] program.mj
#
#   --verbose  show the full compiler log: tokens, syntax tree, symbol table
#   --disasm   print the generated bytecode before running
#   --no-run   compile only
#
# Exit status: 0 = compiled (and ran), 1 = compilation failed.
set -uo pipefail

MJC=/mjc
CP="$MJC/out:$MJC/lib/*:$MJC/config"
verbose=0 disasm=0 run=1
while [[ $# -gt 0 ]]; do
  case "$1" in
    --verbose) verbose=1 ;;
    --disasm)  disasm=1 ;;
    --no-run)  run=0 ;;
    -h|--help) sed -n '2,10p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) break ;;
  esac
  shift
done
src="${1:?usage: mjc.sh [--verbose] [--disasm] [--no-run] program.mj}"
[[ -f "$src" ]] || { echo "mjc: no such file: $src" >&2; exit 1; }

work=$(mktemp -d)
mkdir -p "$work/logs"
name=$(basename "$src" .mj)
obj="$work/$name.obj"

# The lexer only recognises Windows (CRLF) line endings, so normalise the input first.
sed 's/\r$//; s/$/\r/' "$src" > "$work/$name.mj"

# log4j writes logs/ relative to the working directory.
( cd "$work" && java -cp "$CP" rs.ac.bg.etf.pp1.Compiler "$name.mj" "$obj" ) > "$work/compile.log" 2>&1

if [[ $verbose -eq 1 ]]; then
  cat "$work/compile.log"
else
  # Only errors: syntax/semantic errors from log4j, lexical errors and exceptions from stderr.
  # Syntax errors start with a newline, so their text is on the following line.
  awk '/^ERROR/ { sub(/^ERROR +[0-9:,]+ - /, ""); if ($0 == "") getline; print "error: " $0; next }
       /^Lexical error|Exception/ { print }' "$work/compile.log"
fi

if [[ ! -s "$obj" ]]; then
  echo "mjc: compilation of $(basename "$src") failed" >&2
  exit 1
fi
echo "mjc: compiled $(basename "$src") -> $(stat -c %s "$obj") bytes of MicroJava bytecode" >&2

if [[ $disasm -eq 1 ]]; then
  java -cp "$CP" rs.etf.pp1.mj.runtime.disasm "$obj"
fi
if [[ $run -eq 1 ]]; then
  echo "mjc: running on the MicroJava VM" >&2
  java -cp "$CP" rs.etf.pp1.mj.runtime.Run "$obj"
fi
